//! 🔬️ Native AVL insertion keeps original payload custody through paid page and metadata turns.
use super::*;
use semio_framework_value::retirement::RetireOwned;
use semio_framework_value_control_contract::{RetainedCloneGrant,RetirementDemand};
use semio_framework_value_persistent::work::RetainedWorkLedger;
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn close<T:RetireOwned>(value:T){use crate::retirement::controlled::ControlledRetirement;let mut owner=ControlledRetirement::new(value).unwrap_or_else(|(error,_)|panic!("{error}"));let mut release_denied=false;for _ in 0..1_000_000{if owner.terminal_is_empty(){assert!(release_denied);return;}let copy=owner.next_copy_byte_demand().unwrap();let release=owner.next_release_byte_demand().unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(if copy>0{copy}else{release}).unwrap(),maximum_release_bytes:release,maximum_depth:owner.next_depth_demand().unwrap()};if release>0&&!release_denied{let(result,heap)=crate::observe_retirement_allocations(||owner.step(RetainedCloneGrant{maximum_release_bytes:release-1,..g}));assert_eq!(result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));release_denied=true;}let(step,heap)=crate::observe_retirement_allocations(||owner.step(g).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}panic!("numeric original owners did not close");}
#[test]fn neutral_numeric_original_cursor_matches_independent_json_map_and_physical_receipts(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let mut index=NumericIndex::<usize,String>::new();let mut reference=serde_json::Map::new();let mut retired=Vec::new();let mut previous=Vec::new();let mut denied=[false;4];
 for row in fixture["insertions"].as_array().unwrap(){let key=row["key"].as_u64().unwrap()as usize;let value=row["value"].as_str().unwrap().to_owned();reference.insert(key.to_string(),serde_json::Value::String(value.clone()));let mut cursor=NumericWorkInsertCursor::new(key,value);
  for turn in 0..100_000{let d=cursor.next_work_demand();let g=grant(d);for axis in 0..4{let mut under=g;let field=match axis{0=>&mut under.maximum_items,1=>&mut under.maximum_copy_bytes,2=>&mut under.maximum_capacity_bytes,_=>&mut under.maximum_depth};if *field==0||denied[axis]{continue;}*field-=1;let before=index.len();let((result,receipt),heap)=crate::observe_retirement_allocations(||{let mut work=RetainedWorkLedger::new(under);let result=cursor.advance(&mut index,1,&mut work);(result,work.receipt())});assert!(!result.unwrap());assert_eq!(receipt,Default::default());assert_eq!(heap,(0,0));assert_eq!(before,index.len());assert_eq!(cursor.last_turn_work(),0);denied[axis]=true;}
   let((complete,receipt),heap)=crate::observe_retirement_allocations(||{let mut work=RetainedWorkLedger::new(g);let complete=cursor.advance(&mut index,1,&mut work).unwrap();let receipt=work.receipt();if receipt.copied_items>0{let before=index.len();assert!(!cursor.advance(&mut index,1,&mut work).unwrap()||complete);assert_eq!(index.len(),before);} (complete,receipt)});assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));assert!(receipt.fits(g));if complete{if let Some(old)=cursor.take_previous(){previous.push(old);}break;}assert!(turn<99_999);
  }retired.push(cursor);
 }

 let mut removed=Vec::new();let mut retired_removals=Vec::new();let mut removal_denied=[false;3];let mut removal_demanded=[false;3];
 for key in fixture["removals"].as_array().unwrap(){let key=key.as_u64().unwrap()as usize;let expected=reference.remove(&key.to_string()).map(|value|value.as_str().unwrap().to_owned());let mut cursor=NumericWorkRemoveCursor::new(key);
  for turn in 0..100_000{let d=cursor.next_work_demand();let g=grant(d);for axis in 0..3{let mut under=g;let field=match axis{0=>&mut under.maximum_items,1=>&mut under.maximum_copy_bytes,_=>&mut under.maximum_depth};if *field>0{removal_demanded[axis]=true;}if removal_denied[axis]||*field==0{continue;}*field-=1;let before=index.len();let((result,receipt),heap)=crate::observe_retirement_allocations(||{let mut work=RetainedWorkLedger::new(under);let result=cursor.advance(&mut index,1,&mut work);(result,work.receipt())});assert!(!result.unwrap());assert_eq!(receipt,Default::default());assert_eq!(heap,(0,0));assert_eq!(before,index.len());removal_denied[axis]=true;}
   let((complete,receipt),heap)=crate::observe_retirement_allocations(||{let mut work=RetainedWorkLedger::new(g);let complete=cursor.advance(&mut index,1,&mut work).unwrap();(complete,work.receipt())});assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));assert!(receipt.fits(g));if complete{let value=cursor.take_value();assert_eq!(value,expected);if let Some(value)=value{removed.push(value);}break;}assert!(turn<99_999);
  }retired_removals.push(cursor);
 }assert!(removal_denied.iter().any(|axis|*axis));assert!(removal_denied.iter().zip(removal_demanded).all(|(denied,demanded)|*denied||!demanded),"every demanded removal currency must be denied once: denied {removal_denied:?} demanded {removal_demanded:?}");
 let actual:Vec<_>=(0..index.len()).map(|rank|{let(key,value)=index.entry_at_rank(rank).unwrap();(*key,value.as_str())}).collect();let expected:Vec<_>=reference.iter().map(|(key,value)|(key.parse::<usize>().unwrap(),value.as_str().unwrap())).collect();assert_eq!(actual,expected);assert!(denied.into_iter().all(|axis|axis));close((index,retired,previous,removed,retired_removals));
}
